mapper.select:
SELECT COUNT(*)
FROM system_log
WHERE system_status = 'error' AND log_time >= #{since}

SELECT COUNT(DISTINCT user_id)
FROM (
    SELECT user_id FROM api_log WHERE call_time >= #{since}
    UNION
    SELECT user_id FROM generation_history WHERE generation_time >= #{since}
) t

SELECT COUNT(*) AS file_count, COALESCE(SUM(data_size), 0) AS total_size
FROM data_file
WHERE load_time >= #{since}
